-- 建库 / 切库 / 删库
CREATE DATABASE IF NOT EXISTS demo DEFAULT CHARSET utf8mb4;
USE demo;
DROP DATABASE IF EXISTS demo;

CREATE TABLE tb_user (
    id       INT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(20) NOT NULL UNIQUE
);
DESC tb_user;

SELECT id, username FROM tb_user;
SELECT username AS 名字 FROM tb_user;
SELECT DISTINCT age FROM tb_user;

SELECT * FROM tb_user WHERE age > 20;
SELECT * FROM tb_user WHERE age BETWEEN 18 AND 30;
SELECT * FROM tb_user WHERE username LIKE '张%';
